import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class VirtualThreadServer {
    public static void main(String[] args) throws IOException {
        try (ServerSocket serverSocket = new ServerSocket(1234);
             ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
            while (!serverSocket.isClosed()) {
                Socket clientSocket = serverSocket.accept();
                executor.submit(new ClientHandler(clientSocket));
            }
        }
    }

    // Direct single virtual thread launch:
    static void spawnOne(Runnable task) {
        Thread vt = Thread.ofVirtual().start(task);
        System.out.println("Is virtual: " + vt.isVirtual()); // true
    }
}

import java.util.Date;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class ClientRegistry {
    private final AtomicInteger totalConnections = new AtomicInteger(0);
    private final ConcurrentHashMap<String, Date> lastSeen = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, String> activeUsers = new ConcurrentHashMap<>();

    public void recordVisit(String host) {
        int count = totalConnections.incrementAndGet();
        // Atomic: returns previous Date and stores new Date in ONE step
        Date previous = lastSeen.put(host, new Date());
        System.out.println("Visit #" + count + " from " + host + ", prev=" + previous);
    }

    public boolean tryRegisterUsername(String username, String ip) {
        // Atomic check-and-insert: returns null only if username was absent
        return activeUsers.putIfAbsent(username, ip) == null;
    }
}

